import csv,json
from pathlib import Path
import numpy as np
root=Path('/app')
source=list(csv.DictReader((root/'bands.csv').open()))
fit=json.loads((root/'.audit_work/joint_fit.json').read_text())
susceptibility={r['T_K']:float(r['gamma_HS']) for r in csv.DictReader((root/'susceptibility.csv').open())}
temps=['100','150','200','300']
activities={
 'B01':'raman','B02':'neither','B03':'ir','B04':'neither',
 'B05':'raman','B06':'neither','B07':'raman','B08':'raman',
 'B09':'neither','B10':'raman','B11':'raman','B12':'neither',
 'B13':'raman','B14':'neither','B15':'raman','B16':'ir',
 'B17':'neither','B18':'not_applicable',
}
report={
 'state_fractions':{t:susceptibility[t] for t in temps},
 'ls_breathing_mode_band_id':'B05',
 'marker_sets':{'LS':[],'HS':[]},
 'unresolvable_bands':[],
 'bands':[],
}
for row in source:
 band=row['band_id']; data=fit['bands'][band]; state=data['state']
 if state in ('LS','HS'):
  report['marker_sets'][state].append(band)
  fractions=np.mean([data['implied_hs_fraction_by_technique'][k] for k in ('raman_532nm','raman_785nm')],axis=0)
  implied={t:round(float(f),6) for t,f in zip(temps,fractions)}
 else:
  implied={t:None for t in temps}
 if state=='UNRESOLVABLE':report['unresolvable_bands'].append(band)
 report['bands'].append({
  'band_id':band,
  'center_cm1':int(row['center_cm1']),
  'state':state,
  'ls_phase_activity':activities[band],
  'implied_hs_fraction':implied,
 })
(root/'report.json').write_text(json.dumps(report,indent=2,allow_nan=False)+'\n')
# Verify the saved artifact against the input inventory and population constraints.
saved=json.loads((root/'report.json').read_text())
assert set(saved)=={'state_fractions','ls_breathing_mode_band_id','marker_sets','unresolvable_bands','bands'}
assert len(saved['bands'])==len(source)==18
assert len({b['band_id'] for b in saved['bands']})==18
assert {b['band_id'] for b in saved['bands']}=={b['band_id'] for b in source}
centers={b['band_id']:b['center_cm1'] for b in source}
assert set(saved['state_fractions'])==set(temps)
assert all(abs(saved['state_fractions'][t]-susceptibility[t])<=.05 for t in temps)
for state in ('LS','HS'):
 ids=saved['marker_sets'][state]
 assert ids and set(ids)=={b['band_id'] for b in saved['bands'] if b['state']==state}
assert set(saved['unresolvable_bands'])=={b['band_id'] for b in saved['bands'] if b['state']=='UNRESOLVABLE'}
max_error=0.
for b in saved['bands']:
 assert str(b['center_cm1'])==centers[b['band_id']]
 assert b['state'] in ('LS','HS','BOTH','UNRESOLVABLE')
 assert b['ls_phase_activity'] in ('raman','ir','neither','not_applicable')
 assert set(b['implied_hs_fraction'])==set(temps)
 if b['state'] in ('LS','HS'):
  vectors=[list(b['implied_hs_fraction'].values())]+[fit['bands'][b['band_id']]['implied_hs_fraction_by_technique'][k] for k in ('raman_532nm','raman_785nm')]
  for f in vectors:
   assert all(0<=v<=1 for v in f)
   assert all(v<=w for v,w in zip(f,f[1:]))
   error=max(abs(v-susceptibility[t]) for t,v in zip(temps,f))
   assert error<=.10,(b['band_id'],error)
   max_error=max(max_error,error)
 else:assert all(v is None for v in b['implied_hs_fraction'].values())
breathing=next(b for b in saved['bands'] if b['band_id']==saved['ls_breathing_mode_band_id'])
assert breathing['state']=='LS' and breathing['ls_phase_activity']=='raman'
print('Validated report.json: 18 unique bands; 7 LS, 7 HS, 3 BOTH, 1 UNRESOLVABLE.')
print('All marker fractions and both required Raman series pass monotonicity and susceptibility tolerances.')
print(f'Maximum error across the reported values and both individual Raman series: {max_error:.6f}')
print('Breathing-mode carrier:',breathing['band_id'],'at',breathing['center_cm1'],'cm-1')
